import {distanceKm,safeURL,normalizeCatalog} from './core.js?v=20261023-4';
export const ORIGINS={seoul:{name:'서울시청',lat:37.5665,lon:126.9780},busan:{name:'부산시청',lat:35.1796,lon:129.0756}};
export function within(c,b){return Number.isFinite(c.lat)&&Number.isFinite(c.lon)&&c.lat>=b.s&&c.lat<=b.n&&c.lon>=b.w&&c.lon<=b.e;}
export const VERIFIED_TYPES={'osm:way/386241143':{value:'코스',sourceUrl:'https://golfzoncounty.com/golfclub/intro?golfclubSeq=28',basis:'공식 선산 소개: 18홀·72Par·6,517m 코스'}};
export function courseCategory(c){if(VERIFIED_TYPES[c.id])return VERIFIED_TYPES[c.id].value;if(c.facilityType?.verified===true&&safeURL(c.facilityType.sourceUrl)&&['코스','스크린','연습','파크'].includes(c.facilityType.value))return c.facilityType.value;if(c.tags?.golf==='driving_range')return '연습';if(c.tags?.golf==='miniature'||c.tags?.leisure==='miniature_golf')return '미니골프';const name=c.name||'';return /스크린|screen/i.test(name)?'스크린':/연습|driving|practice/i.test(name)?'연습':/파크|park golf/i.test(name)?'파크':'유형 미검증';}
export const categoryPenalty=c=>['스크린','연습','파크','미니골프'].includes(courseCategory(c))?1:0;
export function createDebouncer(callback,delay=300){let timer;return {trigger(){clearTimeout(timer);timer=setTimeout(callback,delay);},cancel(){clearTimeout(timer);}};}
export function viewportCourses(courses,b){return courses.filter(c=>within(c,b));}
export function normalizeNational(data){return (data.courses||[]).filter(c=>Number.isFinite(c.lat)&&Number.isFinite(c.lon)&&!['closed','disused'].includes(c.operatingStatus)).map(c=>({...c,id:c.id,tags:c.tags||{},sourceUrl:c.sourceUrl||`https://www.openstreetmap.org/${c.osmType}/${c.osmId}`,evidence:0,address:c.address||[c.tags?.['addr:city'],c.tags?.['addr:street'],c.tags?.['addr:housenumber']].filter(Boolean).join(' '),distance:null}));}
export function enrichOfficial(courses,catalogData,mapping={}){const official=normalizeCatalog(catalogData),matched=new Set();const items=courses.map(c=>{const match=official.find(o=>(o.official.coordinates?.osm_url&&o.official.coordinates.osm_url===c.sourceUrl)||(mapping.matches||[]).some(m=>m.catalogId===o.id&&m.osmId===c.id));if(!match)return c;matched.add(match.id);return {...c,sourceName:c.name,name:match.name,identityMatch:(mapping.matches||[]).find(m=>m.osmId===c.id)||null,official:match.official,tags:{...c.tags,...match.tags},evidence:match.evidence};});return {items,unmatched:official.filter(c=>!matched.has(c.id))};}
export function naverRating(c){const r=c.naverRating;return r?.verified===true&&Number.isFinite(r.value)&&Number.isFinite(r.count)&&r.count>0?r:null;}
export function feeValue(c,day){const fees=(c.official?.green_fees||[]).filter(f=>f.holes===18&&f.per==='person'&&Number.isFinite(f[day]));return fees.length?Math.min(...fees.map(f=>f[day])):null;}
export function road(c,origin){const r=c.routes?.[origin];return r?.verified===true&&r?.mode==='driving'&&Number.isFinite(r.distanceKm)&&Number.isFinite(r.durationMin)?r:null;}
const numeric=(value)=>Number.isFinite(value)?value:null;
export function sortedCourses(items,sort='recommended'){const value=c=>sort==='weekday'||sort==='weekend'?feeValue(c,sort):sort==='seoul'||sort==='busan'?numeric(road(c,sort)?.distanceKm):null;return [...items].sort((a,b)=>{if(sort==='recommended'){const known=c=>(feeValue(c,'weekday')!==null?4:0)+(c.overview?.verified?2:0)+(c.reviewSummary?.verified?1:0);const diff=known(b)-known(a);if(diff)return diff;const penalty=categoryPenalty(a)-categoryPenalty(b);if(penalty)return penalty;}else if(sort!=='name'){const av=value(a),bv=value(b);if(av===null&&bv!==null)return 1;if(av!==null&&bv===null)return -1;if(av!==null&&bv!==null&&av!==bv)return av-bv;}const namedA=Boolean(a.tags?.name||a.tags?.['name:ko']||a.tags?.['name:en']),namedB=Boolean(b.tags?.name||b.tags?.['name:ko']||b.tags?.['name:en']);if(namedA!==namedB)return namedA?-1:1;return a.name.localeCompare(b.name,'ko')||a.id.localeCompare(b.id);});}
export function shortList(items,{search='',sort='recommended',limit=10,favorites=null}={}){return sortedCourses(items.filter(c=>c.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())&&(!favorites||favorites.has(c.id))),sort).slice(0,limit===20?20:10);}
export function drivingLink(c,origin){const p=ORIGINS[origin];if(!p||!Number.isFinite(c.lat)||!Number.isFinite(c.lon))return null;return `https://map.kakao.com/link/by/car/${encodeURIComponent(p.name)},${p.lat},${p.lon}/${encodeURIComponent(c.name)},${c.lat},${c.lon}`;}
export function naverSearch(c){return `https://map.naver.com/p/search/${encodeURIComponent(c.name)}`;}
export function photoFor(c,{forExport=false}={}){return (c.photos||[]).find(p=>p.courseMatched===true&&((typeof p.courseId==='string'&&p.courseId===c.id)||(typeof p.courseName==='string'&&p.courseName.length>0&&p.courseName===c.name))&&p.license&&safeURL(p.url)&&safeURL(p.sourceUrl)&&(p.exportAllowed===true||(!forExport&&['official_link_preview','official_course_image','tourapi_reference'].includes(p.kind)&&p.displayAllowed===true)))||null;}
export function canonicalSource(c){return safeURL(c.sourceUrl||c.official?.name?.source_url)||null;}
export function mergeById(items,extra){const map=new Map(items.map(c=>[c.id,c]));for(const c of extra)if(!map.has(c.id))map.set(c.id,c);return [...map.values()];}
export function applyEnrichment(courses,data){return courses.map(c=>{let result={...c};const audit=(data.position_audits||[]).find(a=>a.id===(c.official?.id||c.id));if(audit&&audit.status==='official_site_map_point'){result={...result,originalCoordinate:{lat:c.lat,lon:c.lon,sourceUrl:c.sourceUrl},lat:audit.lat,lon:audit.lon,positionAudit:audit,official:c.official?{...c.official,coordinates:{value:{lat:audit.lat,lon:audit.lon},source_url:audit.source_url,provider:'공식 지도점 · 입구 미검증',status:'source-reported'}}:c.official};}const extra=(data.courses||[]).find(x=>x.id===c.official?.id||x.id===c.id);if(extra?.fee&&c.official){const f=extra.fee,o=structuredClone(result.official);o.green_fees=[{currency:f.currency,per:'person',holes:f.holes,weekday:f.weekday,weekend:f.weekend,condition:f.membership+' / '+f.conditions,source_url:f.source_url,checked_at:f.verified_at,valid_from:f.valid_from,status:'source-reported',live_quote:false}];o.caddie_fee={value:f.caddie,currency:'KRW',per:null,holes:f.holes,source_url:f.source_url,checked_at:f.verified_at};o.cart_fee={value:f.cart,currency:'KRW',per:null,holes:f.holes,source_url:f.source_url,checked_at:f.verified_at};o.fee_guide={value:f.source_url};result.official=o;}if(extra?.other_review)result.reviewSummary={...extra.other_review,verified:true,exportAllowed:extra.other_review.rights?.exportAllowed===true};const photo=(data.licensed_photos||[]).find(p=>(typeof p.osm_id==="string"&&p.osm_id===c.id)||(typeof p.osm_url==="string"&&typeof c.sourceUrl==="string"&&p.osm_url===c.sourceUrl)||(typeof p.course_name==="string"&&p.course_name.length>0&&p.course_name===c.name));if(photo?.rights?.reuse&&photo.rights.exportAllowed)result.photos=[{url:photo.url,sourceUrl:photo.source_url,license:photo.license,licenseUrl:photo.license_url,author:photo.author,courseMatched:true,courseId:c.id,courseName:c.name,exportAllowed:true,checkedAt:photo.verified_at,credit:photo.credit}];return result;});}

export const showMapNames=count=>Number.isInteger(count)&&count>0&&count<50;
export function recommendationReasons(c){return [feeValue(c,'weekday')!==null?'공식 18홀 요금 확보':null,c.overview?.verified?'코스 소개 확인':null,c.reviewSummary?.verified?'공개 후기 표본 확인':null].filter(Boolean);}
